// BackupStatus1 Bundle is being packed and encrypted for download.
type BackupStatus1 struct {
	State BackupStatus1State `json:"state"`
}

// BackupStatus1State defines model for BackupStatus.1.State.
type BackupStatus1State string

// BackupStatus2 An import is in progress — `phase` describes where.
type BackupStatus2 struct {
	// Phase Phase of an in-flight restore. Emitted as progress events so the UI can
	// show a spinner with meaningful status text.
	//
	// The restore pipeline is strictly sequential — no phase is ever skipped on
	// the happy path, and a failure preserves the phase it occurred in so the
	// operator can tell *where* the restore broke.
	Phase RestorePhase       `json:"phase"`
	State BackupStatus2State `json:"state"`
}

// BackupStatus2State defines model for BackupStatus.2.State.
type BackupStatus2State string

// BackupStatus3 The last import failed; the error is retained until the next operation.
type BackupStatus3 struct {
	Reason string             `json:"reason"`
	State  BackupStatus3State `json:"state"`
}

// BackupStatus3State defines model for BackupStatus.3.State.
type BackupStatus3State string

// BackupStatusResponse Response for `GET /api/backup/status`.
type BackupStatusResponse struct {
	// Status Coarse subsystem status surfaced by `GET /api/backup/status` and the web UI.
	Status BackupStatus `json:"status"`
}

