// Blocklist A URL-sourced domain blocklist scoped to a DNS filter profile.
type Blocklist struct {
	// ConsecutiveFailures Failed refresh attempts since the last success, zeroed by any
	// successful refresh. Drives the cron runner's exponential backoff:
	// a failure leaves `last_updated` untouched, so without this the
	// every-minute tick would keep re-downloading a broken feed forever.
	ConsecutiveFailures int32     `json:"consecutive_failures"`
	CreatedAt           time.Time `json:"created_at"`

	// CronSchedule Cron expression for update schedule (e.g. "0 3 * * *").
	CronSchedule string             `json:"cron_schedule"`
	Enabled      bool               `json:"enabled"`
	EntryCount   int64              `json:"entry_count"`
	Id           openapi_types.UUID `json:"id"`

	// LastError Error message from the most recent failed download/parse, if any.
	// Cleared on a successful refresh. Surfaced in the Ad Blocking UI so
	// users can diagnose blocklist issues without inspecting daemon logs.
	LastError *string `json:"last_error,omitempty"`

	// LastErrorAt Timestamp of the most recent failed download/parse.
	LastErrorAt *time.Time         `json:"last_error_at,omitempty"`
	LastUpdated *time.Time         `json:"last_updated,omitempty"`
	Name        string             `json:"name"`
	ProfileId   openapi_types.UUID `json:"profile_id"`
	UpdatedAt   time.Time          `json:"updated_at"`
	Url         string             `json:"url"`
}

// BundleManifest Metadata describing a bundle. Serialised as `manifest.json` inside the tar.
//
// The manifest is the first entry extracted during validation so we can
// reject incompatible bundles before touching any daemon state.
type BundleManifest struct {
	// BundleFormatVersion Bundle layout version. See `CURRENT_BUNDLE_FORMAT_VERSION`.
	BundleFormatVersion int32 `json:"bundle_format_version"`

	// CreatedAt UTC timestamp the bundle was created.
	CreatedAt time.Time `json:"created_at"`

	// HostId Opaque identifier for the source host (hostname or a stable system id).
	// Surfaced in the restore preview so operators can confirm they're not
	// restoring a bundle from the wrong machine.
	HostId string `json:"host_id"`

	// KeyCount Number of `WireGuard` key files included in the bundle. Surfaced in the
	// preview UI so the operator knows exactly what will be overwritten.
	KeyCount int32 `json:"key_count"`

	// SchemaVersion Highest applied sqlx migration version at export time.
	SchemaVersion int64 `json:"schema_version"`

	// WardnetVersion Daemon version (from `WARDNET_VERSION`) that produced the bundle, e.g.
	// `0.2.0` or `0.2.1-dev.7+gabc1234`. Informational — not used for compat.
	WardnetVersion string `json:"wardnet_version"`
}

