// LoginWithBody performs a POST /api/auth/login (the `Login` operationId) request,
// with any type of body and a specified content type.
//
// Log in with username and password. On success, sets a `wardnet_session` cookie the browser replays on subsequent admin-gated requests. The JSON body also carries the raw `token` and `expires_in_seconds` so non-browser clients (scripts, the `wctl` CLI, third-party integrations) can replay the token via `Authorization: Bearer <token>` without a cookie jar.
func (c *Client) LoginWithBody(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewLoginRequestWithBody(c.Server, contentType, body)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

